import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:path/path.dart' as p;

/// The Apple runners are generated by `flutter create` and then patched from
/// `platform_overrides/` by `scripts/bootstrap_flutter_project.sh`. Both copies
/// are committed, so they must never drift apart.
void main() {
  for (final platform in ['ios', 'macos']) {
    test('$platform runner matches platform_overrides', () {
      final overrides = Directory('platform_overrides/$platform/Runner');
      final files = overrides.listSync().whereType<File>().toList();
      expect(files, isNotEmpty);
      for (final file in files) {
        final runnerCopy = File(
          p.join(platform, 'Runner', p.basename(file.path)),
        );
        expect(
          runnerCopy.existsSync(),
          isTrue,
          reason: '${runnerCopy.path} is missing',
        );
        expect(
          runnerCopy.readAsStringSync(),
          file.readAsStringSync(),
          reason:
              '${runnerCopy.path} differs from ${file.path}. Edit the '
              'override and copy it, or run the bootstrap script.',
        );
      }
    });

    test('$platform Xcode project compiles every override Swift file', () {
      final project = File(
        '$platform/Runner.xcodeproj/project.pbxproj',
      ).readAsStringSync();
      final swiftFiles = Directory('platform_overrides/$platform/Runner')
          .listSync()
          .whereType<File>()
          .where((file) => file.path.endsWith('.swift'))
          .map((file) => p.basename(file.path));
      for (final name in swiftFiles) {
        expect(
          project,
          contains('/* $name in Sources */'),
          reason: '$name is not in the $platform Sources build phase',
        );
      }
    });
  }

  test('android runner matches platform_overrides', () {
    const package = 'app/src/main/kotlin/io/github/finngrndl/aquarecover';
    final overrides = Directory('platform_overrides/android/$package');
    final files = overrides.listSync().whereType<File>().toList();
    expect(files, isNotEmpty);
    for (final file in files) {
      final runnerCopy = File(
        p.join('android', package, p.basename(file.path)),
      );
      expect(
        runnerCopy.readAsStringSync(),
        file.readAsStringSync(),
        reason: '${runnerCopy.path} differs from ${file.path}.',
      );
    }
  });

  for (final shared in ['AquaMediaPipeline', 'AquaTimelineRenderer']) {
    test(
      '$shared.swift is identical on iOS and macOS and platform neutral',
      () {
        final ios = File(
          'platform_overrides/ios/Runner/$shared.swift',
        ).readAsStringSync();
        final macos = File(
          'platform_overrides/macos/Runner/$shared.swift',
        ).readAsStringSync();
        expect(macos, ios);
        for (final module in ['Flutter', 'FlutterMacOS', 'UIKit', 'AppKit']) {
          expect(ios, isNot(contains('import $module\n')));
        }
      },
    );
  }
}
